const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const montePisano = ee.Geometry.Point(10.518, 43.753); // Approximate center of Monte Pisano, Italy
  const startDate = '2019-02-25';
  const endDate = '2019-02-26'; // Filter for the specific day

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
    .filterBounds(montePisano)
    .filterDate(startDate, endDate);

  const colSize = await collection.size().getInfo();
  if (colSize === 0) {
    console.log("No Landsat 8 images found for Monte Pisano on Feb 25, 2019.");
    console.log("C1");
    return;
  }

  // Get the specific image (there should be only one or two passes for a single day)
  const image = ee.Image(collection.first());
  if (!image) {
    console.log("Could not retrieve the first image from the collection.");
    console.log("C3");
    return;
  }

  // 3. Processing (Cloud Masking - using Landsat 8 SR QA band)
  // Function to mask clouds based on the QA_PIXEL band
  function maskL8sr(image) {
    const qa = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
      .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask).select(['B4', 'B3', 'B2', 'B6', 'B7']); // Select some relevant bands
  }

  const maskedImage = maskL8sr(image);

  // Check valid pixels after masking in a relevant band (e.g., Red B4)
  const countRegion = maskedImage.select('B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: montePisano.buffer(5000), // Check a 5km buffer around the point
    scale: 30, // Landsat resolution
    maxPixels: 1e9
  });

  const validPixels = await countRegion.get('B4').getInfo();

  console.log(`Initial Landsat 8 images: ${colSize}`);
  console.log(`Valid pixels after cloud mask (B4) around Monte Pisano: ${validPixels}`);

  if (validPixels === 0) {
    console.log("No valid pixels remain after cloud masking around Monte Pisano. The fire event or smoke might be masked out.");
    console.log("C2");
    return;
  }

  // 4. Calculation / Analysis for smoke direction
  // Determining smoke plume direction programmatically (e.g., eastern)
  // would require advanced image processing techniques to detect the fire source,
  // identify the smoke plume's extent, calculate its centroid or major axis,
  // and then compare its orientation to cardinal directions.
  // This is a complex visual interpretation task that cannot be reliably
  // automated with simple Earth Engine aggregate functions or band calculations
  // for a "Yes/No" answer based purely on code.
  // GEE is not designed for advanced visual pattern recognition to this degree
  // without specialized algorithms and models.

  // To provide "evidence", we can output image metadata or a visual representation link.
  // For the purpose of this automated script, we must state the limitation.

  const imageId = image.id().getInfo();
  const imageTime = ee.Date(image.get('system:time_start')).format().getInfo();
  const imageCloudCover = image.get('CLOUD_COVER').getInfo();

  console.log(`Image ID: ${imageId}`);
  console.log(`Image Acquisition Time: ${imageTime}`);
  console.log(`Image Cloud Cover: ${imageCloudCover}%`);

  // We can't programmatically determine the smoke plume direction as a simple A/B.
  // This is a qualitative visual analysis question.
  // Thus, the calculation cannot be performed with the provided tools for a definitive A/B answer.

  console.log("C3"); // Calculation Failure, as the type of calculation required (visual interpretation of smoke direction) cannot be performed programmatically with simple GEE methods.
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
